(()=>{const root=document.documentElement,system=matchMedia('(prefers-color-scheme: dark)');let mode='system';try{mode=localStorage.getItem('rebate-theme')||'system'}catch{}if(!['system','light','dark'].includes(mode))mode='system';const apply=()=>{const dark=mode==='dark'||mode==='system'&&system.matches;root.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#141518':'#fafafa')};apply();system.addEventListener('change',apply);document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('themeSelect');select.value=mode;select.onchange=()=>{mode=select.value;try{localStorage.setItem('rebate-theme',mode)}catch{}apply()}})})();
